package com.mall.controller;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.mall.common.result.PageResult; import com.mall.common.result.Result;
import com.mall.entity.CustomerServiceMessage; import com.mall.entity.CustomerServiceTicket; import com.mall.service.CustomerServiceTicketService;
import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/service-tickets") public class CustomerServiceTicketController { private final CustomerServiceTicketService service; public CustomerServiceTicketController(CustomerServiceTicketService service){this.service=service;} @PostMapping public Result<CustomerServiceTicket> create(@AuthenticationPrincipal Long userId,@RequestBody TicketRequest r){return Result.success(service.create(userId,r.ticket(),r.content()));} @GetMapping public Result<PageResult<CustomerServiceTicket>> page(@AuthenticationPrincipal Long userId,@RequestParam(defaultValue="1")Integer current,@RequestParam(defaultValue="20")Integer size){Page<CustomerServiceTicket>p=service.pageForUser(userId,current,size);return Result.success(new PageResult<>(p.getTotal(),p.getRecords(),current,size));} @GetMapping("/{id}/messages") public Result<List<CustomerServiceMessage>> messages(@AuthenticationPrincipal Long userId,@PathVariable Long id){return Result.success(service.messages(userId,id,false));} @PostMapping("/{id}/messages") public Result<Void> reply(@AuthenticationPrincipal Long userId,@PathVariable Long id,@RequestBody MessageRequest r){service.reply(userId,id,"USER",r.content(),false);return Result.success("发送成功",null);} public record TicketRequest(CustomerServiceTicket ticket,String content){} public record MessageRequest(String content){} }
